class Solution:
    def numberOfPaths(self, n: int, corridors: List[List[int]]) -> int:
        adj = [set() for _ in range(n + 1)]
        for a, b in corridors:
            adj[a].add(b)
            adj[b].add(a)

        count = 0
        for i in range(1, n + 1):
            for j in range(i + 1, n + 1):
                if j not in adj[i]:
                    continue
                for k in range(j + 1, n + 1):
                    if k in adj[i] and k in adj[j]:
                        count += 1
        return count

