class Solution {
public:
    int numberOfPaths(int n, vector<vector<int>>& corridors) {
        vector<unordered_set<int>> adj(n + 1);
        for (auto& e : corridors) {
            adj[e[0]].insert(e[1]);
            adj[e[1]].insert(e[0]);
        }
        int count = 0;
        for (int i = 1; i <= n; i++)
            for (int j = i + 1; j <= n; j++) {
                if (!adj[i].count(j)) continue;
                for (int k = j + 1; k <= n; k++)
                    if (adj[i].count(k) && adj[j].count(k)) count++;
            }
        return count;
    }
};

