class Solution {
public:
    int numberOfPaths(int n, vector<vector<int>>& corridors) {
        vector<unordered_set<int>> adj(n + 1);
        for (auto& e : corridors) {
            adj[e[0]].insert(e[1]);
            adj[e[1]].insert(e[0]);
        }
        int count = 0;
        for (auto& e : corridors) {
            const unordered_set<int>* s = &adj[e[0]];
            const unordered_set<int>* b = &adj[e[1]];
            if (s->size() > b->size()) swap(s, b);
            for (int w : *s)
                if (b->count(w)) count++;
        }
        return count / 3;
    }
};

