class Solution {
    public int numberOfPaths(int n, int[][] corridors) {
        List<Set<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) adj.add(new HashSet<>());
        for (int[] e : corridors) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        int count = 0;
        for (int[] e : corridors) {
            Set<Integer> s = adj.get(e[0]), b = adj.get(e[1]);
            if (s.size() > b.size()) {
                Set<Integer> tmp = s;
                s = b;
                b = tmp;
            }
            for (int w : s)
                if (b.contains(w)) count++;
        }
        return count / 3;
    }
};

